$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ClosureResults";$name='m78-closure-current-signals';$project="$out\current-signals-project";$exe="$root\Build\Release\m78-closure-signal_application_final.exe"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if((Test-Path "$out\$name.json") -or (Test-Path $project)){throw 'Preserve existing copied fixture/result'}
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-closure-current-signals-manifest.json").Content|ConvertFrom-Json
 $old="$root\Source\projects\signals_lab";$oldFiles=@(Get-ChildItem $old -Recurse -File|ForEach-Object {@{path=$_.FullName.Substring($old.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName).Hash.ToLower()}})
 $zip="$out\current-signals-project.zip";Invoke-WebRequest -UseBasicParsing "$base/m78-closure-current-signals.zip" -OutFile $zip;if((Get-Item $zip).Length -ne $m.zipBytes -or (Get-FileHash $zip).Hash.ToLower() -ne $m.zipSHA256){throw 'Copied project archive mismatch'};Expand-Archive $zip $project
 foreach($f in $m.files){$p=Join-Path $project $f.path;if((Get-Item $p).Length -ne $f.bytes -or (Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw 'Copied current project mismatch'}}
 Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-signal_application_final-m78-closure-signal_application_final.exe.bin" -OutFile $exe;if((Get-Item $exe).Length -ne $m.executableBytes -or (Get-FileHash $exe).Hash.ToLower() -ne $m.executableSHA256){throw 'Reused exact test binary mismatch'}
 $env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$out\current-signals-temp";$env:TMP=$env:TEMP;$env:APPDATA="$out\current-signals-userdata\Roaming";$env:LOCALAPPDATA="$out\current-signals-userdata\Local";New-Item -ItemType Directory $env:TEMP,$env:APPDATA,$env:LOCALAPPDATA -Force|Out-Null
 foreach($n in @('M78_DIAGNOSTIC_PERSIST_DRIVE_IMPULSES','JUDAS_DIAGNOSTIC_RESTORE_DRIVES','JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE','JUDAS_BOUNDARY_REPLAY_MODE','JUDAS_BOUNDARY_DISCARD_FIRST_JOINT_SEEDS','JUDAS_BOUNDARY_ORACLE_FIRST_SOLVE','JUDAS_BOUNDARY_ORACLE_ALL_SOLVES','JUDAS_DIAGNOSTIC_CONTINUE_WRITE','JUDAS_TEST_SCRIPT')){[Environment]::SetEnvironmentVariable($n,$null,'Process')}
 $runs=@();foreach($loading in @($false,$true)){
  $id=if($loading){'current-signals-read'}else{'current-signals-write'};$args=@(('"'+$project+'\signals_lab.judasproj"'));if($loading){$args+=@('load')};$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $exe -ArgumentList $args -WorkingDirectory "$root\Source" -PassThru -RedirectStandardOutput "$out\m78-closure-$id.stdout.log" -RedirectStandardError "$out\m78-closure-$id.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;throw 'Owned signal test timeout'};$p.Refresh();$exit=$p.ExitCode;$p.Dispose();$watch.Stop();$runs+=@(@{run=$id;exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executableSHA256=$m.executableSHA256;project=$project;arguments=$args});Upload "$out\m78-closure-$id.stdout.log" "m78-closure-$id.stdout.log";Upload "$out\m78-closure-$id.stderr.log" "m78-closure-$id.stderr.log"
 }
 foreach($f in $oldFiles){$p=Join-Path $old $f.path;if((Get-Item $p).Length -ne $f.bytes -or (Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw 'Historical guest fixture unexpectedly changed'}}
 $saved=@(Get-ChildItem "$out\current-signals-userdata" -Recurse -File|ForEach-Object {$f=$_;Upload $f.FullName ("m78-closure-current-signals-save-"+$f.Name);@{path=$f.FullName;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}})
 @{scope=$m.scope;runs=$runs;copiedProject=$project;verifiedCurrentFiles=$m.files;historicalProjectFiles=$oldFiles;historicalProjectUnchanged=$true;inputTestSHA256=$m.testSHA256;executableSHA256=$m.executableSHA256;reusedBinaryNoCompilation=$true;savedFiles=$saved;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content "$out\$name.json" -Encoding UTF8;Upload "$out\$name.json" "$name.json"
 if((Get-Item $exe).Length -ne $m.executableBytes -or (Get-FileHash $exe).Hash.ToLower() -ne $m.executableSHA256){throw 'Final reused binary differs'};Remove-Item -LiteralPath $exe;@{scope='Retired only restored named generated test executable already losslessly host-verified and originally approved; sources, original project, saves and logs unchanged';path=$exe;bytes=$m.executableBytes;sha256=$m.executableSHA256;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json|Set-Content "$out\$name-cleanup.json" -Encoding UTF8;Upload "$out\$name-cleanup.json" "$name-cleanup.json"
 if(@($runs|Where-Object {$_.exitCode -ne 0}).Count){throw 'Actual current-project signals failure'}
}catch{$_|Out-String|Set-Content "$out\$name-error.txt";Upload "$out\$name-error.txt" "$name-error.txt";exit 1}
